#
# IC18 (C3CBND000046) from 0x10000 to the end: the built-in "Technics Rhythms" style
# resource, which the firmware finds at 0x40010000 (StyleResourceWindowProbe, its third
# window) and opens with StyleBuiltinNameTableInit. GENERATED by tools/gen_ic18_rhythm_s.py
# (`make ic18-rhythm-src`); notes/ic18-rhythm-rom.md is the format and its evidence.
#   169 styles x 20 variations, 8 count-in patterns; 220 rhythms in all with the
#   51 that live in the table ROM.
#
# Every multi-byte field is BIG-endian (.be16/.be24): the firmware reads this resource
# through LoadU16BE / LoadU24BE / SumU16BE, although the MN10300 is little-endian.
# Offsets are from the resource start, TechnicsRhythms.
#
# The event streams of the styles are pulled from the reference image, one labelled
# .incbin_range each: they are the ROM's music, which this public repository does not
# carry in bulk. The generator checks every one of them event by event.

.mnbase 0x40000000

# ---- record macros ----------------------------------------------------------------
# A part set-up (15 bytes): each byte is the value of one controller, in the order of
# the firmware's field table 0x485B77D4 (CC -> field map 0x485B781C). The firmware
# copies the eight of a style into the part table 0x5003A37C (func_4844187A); the
# set-up events of a variation then overwrite single fields (func_48441EB4).
#   mode     CC97; 0x00 on the two drum parts, 0x08 on the others   [INFERENCE: role]
#   volume   CC7
#   prog, bank_lsb, bank_msb   the three data bytes of the part's program change
#            (StyleRecordToTemplate); bank_msb is 0x26 on the drum parts, 0x20 on the
#            others. [INFERENCE] the names of the two bank bytes
#   cc94     CC94          reverb   CC91          chorus   CC93          pan   CC10
#   cc96, cc82, cc83, cc80, cc81, cc92   those controllers
.macro style_part mode, volume, prog, bank_lsb, bank_msb, cc94, reverb, chorus, pan, cc96, cc82, cc83, cc80, cc81, cc92
	.byte	\mode, \volume, \prog, \bank_lsb, \bank_msb, \cc94, \reverb, \chorus, \pan
	.byte	\cc96, \cc82, \cc83, \cc80, \cc81, \cc92
.endm
# The two sound-unit keys of a style (record +0x0D, 4 bytes; func_484420EF): each pair is
# a 14-bit value, 7 bits a byte, low byte first (bit 6 of the second byte adds 0x10000);
# they are stored to parameter keys 0xB044 and 0xB054, the sound-unit groups 0xB040 and
# 0xB050 (SndUnitRefreshGroups56). Bit 7 of the second byte goes to key 0xB001.
.macro style_units unit5_lo, unit5_hi, unit6_lo, unit6_hi
	.byte	\unit5_lo, \unit5_hi, \unit6_lo, \unit6_hi
.endm
# The 20 slot offsets of a style (record +0x8A, from the record): StyleNameCommit loads
# them into 0x50034BCC[]. Slots 0-11 are four variations, each a main pattern and two
# fill-ins (only slot % 3 == 0 has a name in a MEMORY style: MemStyleVarCopy); 12-19 are
# four A/B pairs, 12-15 intros, 16-19 endings (func_4844232B tells (slot - 12) % 4 < 2,
# number 1, from number 2). [INFERENCE] the intro/ending and fill-in roles
.macro style_slots s
	.be24	\s_Var1 - \s, \s_Var1Fill1 - \s, \s_Var1Fill2 - \s
	.be24	\s_Var2 - \s, \s_Var2Fill1 - \s, \s_Var2Fill2 - \s
	.be24	\s_Var3 - \s, \s_Var3Fill1 - \s, \s_Var3Fill2 - \s
	.be24	\s_Var4 - \s, \s_Var4Fill1 - \s, \s_Var4Fill2 - \s
	.be24	\s_Intro1A - \s, \s_Intro1B - \s, \s_Intro2A - \s, \s_Intro2B - \s
	.be24	\s_Ending1A - \s, \s_Ending1B - \s, \s_Ending2A - \s, \s_Ending2B - \s
.endm
# A variation record (StyleRecordBindBuiltin): bars - 1 (-> 0x50122DCE), beats a bar - 1
# (-> 0x50122DCF; StyleBoundRecByteCfLow3), two part numbers for the sound units (0xFF =
# none; func_48442164, key 0xB048 [INFERENCE: the role]), the length of the set-up
# events, the events; then the length of the event stream and the stream.
.macro var_head v, bars, beats, unit_part_a, unit_part_b
	.byte	\bars - 1, \beats - 1, \unit_part_a, \unit_part_b
	.be16	\v_SetupEnd - \v_Setup
\v_Setup:
.endm
.macro var_events v
\v_SetupEnd:
	.be24	\v_EventsEnd - \v_Events
.endm
.macro var_end v
\v_EventsEnd:
.endm
# Events (RhyEventLenByStatus): the low nibble of a status byte is the part, 0-7.
.macro ev_cc part, ctl, value
	.byte	0xb0 + \part, \ctl, \value
.endm
.macro ev_pc part, prog, bank_lsb, bank_msb
	.byte	0xc0 + \part, \prog, \bank_lsb, \bank_msb
.endm
# A note: key, velocity, then three bytes. [INFERENCE] gate_lo/gate_hi a 14-bit length
# and `rule` the chord-adaptation class: it is 0 on every note of the two drum parts.
.macro ev_note part, key, velocity, gate_lo, gate_hi, rule
	.byte	0x90 + \part, \key, \velocity, \gate_lo, \gate_hi, \rule
.endm
# A position byte: the tick in the beat (0-95, 96 a beat) of the events after it.
.macro ev_at tick
	.byte	\tick
.endm
.macro ev_beat
	.byte	0xf4
.endm
.macro ev_end
	.byte	0xf5
.endm
.macro sidx_style no
	.be16	\no
.endm
.macro sidx_alias entry
	.be16	0x8000 + \entry
.endm
.macro sidx_table no
	.be16	0x4000 + \no
.endm

# ---- the header (StyleBuiltinNameTableInit, StyleResourceVerify) -----------------
.org 0x10000
TechnicsRhythms:
	.ascii	"Technics Rhythms"		# strncmp with the firmware's 0x4872980C
	.be16	0xe2da			# SumU16BE of the halfwords below, StyleResourceVerify
	.be24	0x100000			# checksum start, from TechnicsRhythms: file 0x110000, inside a stream
	.be24	0x100000			# checksum length in halfwords (2 MB)
	.be24	RhythmCountBlock - TechnicsRhythms
	.be24	RhythmStyleIndex - TechnicsRhythms	# -> 0x50034B7C
	.be24	RhythmStyleTable - TechnicsRhythms	# -> 0x50034B80
	.be24	RhythmCountInTable - TechnicsRhythms	# -> 0x50034B84
	.be24	Style_8BtStandard - TechnicsRhythms	# -> 0x50034B88, the fallback style
RhythmCountBlock:
	.be16	0			# TODO: not read
	.be16	220			# the rhythm count -> 0x50034B74; the index's limit
	.be16	96			# [INFERENCE] ticks a beat: every position byte of every stream is 0..95
	.byte	13, 8, 4, 2, 2, 2	# [INFERENCE] name length 13, 8 parts, 4 variations, 2 fill-ins, 2 intros,
					# 2 endings (4 + 4x2 + 2x2 + 2x2 = 20 slots); nothing reads them

# ---- the style-ID index (StyleBuiltinNameResolve) --------------------------------
# 2048 entries; entry ((id & 0x0F00) >> 1) | (id & 0x7F) serves style-ID id. An entry
# below 220 is a style of this table, 0x8000 + n sends the ID to entry n, 0x4000 + n to
# style n of the table ROM's secondary sub-table (TableRomStyleSubTablePtr). Every ID
# resolves to some style.
